const CONFIG={phone:"+919876543210",wa:"919876543210",brand:"Royal Spice"};document.addEventListener("DOMContentLoaded",()=>{const loader=document.querySelector(".loader");setTimeout(()=>loader&&loader.classList.add("hide"),450);document.querySelectorAll("[data-year]").forEach(e=>e.textContent=new Date().getFullYear());document.querySelectorAll("[data-phone]").forEach(e=>e.textContent=CONFIG.phone);document.querySelectorAll("[data-call]").forEach(e=>e.href=`tel:${CONFIG.phone}`);document.querySelectorAll("[data-wa]").forEach(e=>e.href=`https://wa.me/${CONFIG.wa}`);const nav=document.querySelector(".navbar"),bar=document.getElementById("progressBar"),topBtn=document.querySelector(".back-top");function onScroll(){const y=scrollY,h=document.documentElement.scrollHeight-innerHeight;nav&&nav.classList.toggle("scrolled",y>20);topBtn&&topBtn.classList.toggle("show",y>500);bar&&(bar.style.width=`${h?y/h*100:0}%`)}addEventListener("scroll",onScroll,{passive:true});onScroll();document.querySelectorAll('a[href^="#"]').forEach(a=>a.addEventListener("click",e=>{const t=document.querySelector(a.getAttribute("href"));if(t){e.preventDefault();t.scrollIntoView({behavior:"smooth",block:"start"})}}));document.querySelector(".back-top")?.addEventListener("click",()=>scrollTo({top:0,behavior:"smooth"}));const typed=document.querySelector(".typing");if(typed){const words=["Fine Indian Dining","Fresh Daily Flavors","Luxury Family Moments"];let wi=0,ci=0,del=false;setInterval(()=>{const w=words[wi];typed.textContent=w.slice(0,ci);ci+=del?-1:1;if(ci>w.length+6)del=true;if(ci<0){del=false;wi=(wi+1)%words.length;ci=0}},95)}const io=new IntersectionObserver(entries=>entries.forEach(en=>{if(en.isIntersecting){en.target.classList.add("visible");if(en.target.matches("[data-count]"))countUp(en.target);io.unobserve(en.target)}}),{threshold:.16});document.querySelectorAll(".reveal,[data-count]").forEach(e=>io.observe(e));function countUp(el){const target=+el.dataset.count,dur=1400,start=performance.now();function tick(now){const p=Math.min((now-start)/dur,1);el.textContent=Math.floor(target*(1-Math.pow(1-p,3))).toLocaleString();p<1&&requestAnimationFrame(tick)}requestAnimationFrame(tick)}document.querySelectorAll(".filter-btn").forEach(btn=>btn.addEventListener("click",()=>{const group=btn.closest("[data-filter-group]"),filter=btn.dataset.filter;group.querySelectorAll(".filter-btn").forEach(b=>b.classList.remove("active"));btn.classList.add("active");document.querySelectorAll("[data-category]").forEach(card=>{const show=filter==="all"||card.dataset.category.split(" ").includes(filter);card.style.opacity=show?"1":"0";card.style.transform=show?"scale(1)":"scale(.92)";setTimeout(()=>card.style.display=show?"block":"none",show?0:220)})}));const lightbox=document.querySelector(".lightbox");document.querySelectorAll(".gallery-item img").forEach(img=>img.addEventListener("click",()=>{if(!lightbox)return;lightbox.querySelector("img").src=img.src;lightbox.querySelector("img").alt=img.alt;lightbox.classList.add("show")}));lightbox?.addEventListener("click",()=>lightbox.classList.remove("show"));document.addEventListener("keydown",e=>{if(e.key==="Escape")lightbox?.classList.remove("show")});document.querySelectorAll("form[data-validate]").forEach(form=>form.addEventListener("submit",e=>{e.preventDefault();let ok=true;form.querySelectorAll("[required]").forEach(input=>{const valid=input.type==="email"?/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(input.value):input.type==="tel"?/^[0-9+\-\s]{8,16}$/.test(input.value):input.value.trim().length>1;input.classList.toggle("is-invalid",!valid);ok=ok&&valid});notify(ok?form.dataset.success||"Thank you. We will contact you soon.":"Please check the highlighted fields.",ok);if(ok)form.reset()}));function notify(msg,ok=true){let t=document.querySelector(".toast-note");if(!t){t=document.createElement("div");t.className="toast-note";document.body.appendChild(t)}t.textContent=msg;t.style.background=ok?"#1B1B1B":"#C62828";t.classList.add("show");setTimeout(()=>t.classList.remove("show"),3200)}document.querySelector(".dark-toggle")?.addEventListener("click",()=>{document.body.classList.toggle("dark-mode");localStorage.setItem("theme",document.body.classList.contains("dark-mode")?"dark":"light")});localStorage.getItem("theme")==="dark"&&document.body.classList.add("dark-mode")});
